/**
 * Embedded copies of the canonical `stdlib/` prelude sources. Do not edit by hand.
 * Regenerate with `npm run generate:prelude`; a conformance test asserts these
 * never drift from the originals.
 */

export const PRELUDE_SOURCES: Readonly<Record<string, string>> = {
  "Bool.hex":
    "// The boolean type. Constructor order `False | True` is normative: it is what makes\n"
    + "// the derived `Ord` order `False < True`.\n"
    + "export union Bool derives (Eq, Ord, Show, Hash) =\n"
    + "    | False\n"
    + "    | True\n",
  "Prelude.hex":
    "// The outcome of comparing two values, as produced by `Ord.compare`.\n"
    + "export union Ordering derives (Eq, Show) =\n"
    + "    | Less\n"
    + "    | Equal\n"
    + "    | Greater\n",
  "Option.hex":
    "// The canonical optional-value union used by total standard-library accessors.\n"
    + "export union Option(a) derives (Eq, Show) =\n"
    + "    | Some(value: a)\n"
    + "    | None\n",
  "Seq.hex":
    "// `Option`, `Some`, and `None` are implicitly in scope via the prelude.\n"
    + "\n"
    + "// A lazy, immutable, possibly infinite sequence of `a`s. Constructing a\n"
    + "// combinator computes nothing; each element is produced on demand by `next`.\n"
    + "export opaque record Seq(a) = { pull: () -> Option((a, Seq(a))) }\n"
    + "\n"
    + "// Computes each element of `source` at most once however often the result is\n"
    + "// traversed, at the cost of retaining what has been produced.\n"
    + "extern from \"hex:intrinsic\"\n"
    + "    export fun seqMemoize as memoize<a>(source: Seq(a)): Seq(a)\n"
    + "\n"
    + "// Drives one step: the head element and the successor sequence, or `None` when\n"
    + "// exhausted. `source` itself is unchanged.\n"
    + "export let next(source: Seq(a)): Option((a, Seq(a))) = (source.pull)()\n"
    + "\n"
    + "// Producers, and combinators whose step yields at most one element per pull.\n"
    + "\n"
    + "export let empty: Seq(a) = Seq({ pull = () => None })\n"
    + "\n"
    + "export let singleton(value: a): Seq(a) = Seq({ pull = () => Some((value, empty)) })\n"
    + "\n"
    + "export let cons(value: a, rest: Seq(a)): Seq(a) = Seq({ pull = () => Some((value, rest)) })\n"
    + "\n"
    + "export fun iterate(seed: a, step: a -> a): Seq(a) =\n"
    + "    Seq({ pull = () => Some((seed, iterate(step(seed), step))) })\n"
    + "\n"
    + "export fun map(source: Seq(a), transform: a -> b): Seq(b) =\n"
    + "    Seq({ pull = () =>\n"
    + "        match next(source)\n"
    + "            None => None\n"
    + "            Some((value, rest)) => Some((transform(value), map(rest, transform)))\n"
    + "    })\n"
    + "\n"
    + "export fun take(source: Seq(a), count: Int): Seq(a) =\n"
    + "    if count <= 0 then\n"
    + "        empty\n"
    + "    else\n"
    + "        Seq({ pull = () =>\n"
    + "            match next(source)\n"
    + "                None => None\n"
    + "                Some((value, rest)) => Some((value, take(rest, count - 1)))\n"
    + "        })\n"
    + "\n"
    + "export fun takeWhile(source: Seq(a), keep: a -> Bool): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        match next(source)\n"
    + "            None => None\n"
    + "            Some((value, rest)) =>\n"
    + "                if keep(value) then\n"
    + "                    Some((value, takeWhile(rest, keep)))\n"
    + "                else\n"
    + "                    None\n"
    + "    })\n"
    + "\n"
    + "export fun unfold(seed: b, produce: b -> Option((a, b))): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        match produce(seed)\n"
    + "            None => None\n"
    + "            Some((value, nextSeed)) => Some((value, unfold(nextSeed, produce)))\n"
    + "    })\n"
    + "\n"
    + "export fun zipWith(left: Seq(a), right: Seq(b), combine: (a, b) -> c): Seq(c) =\n"
    + "    Seq({ pull = () =>\n"
    + "        match next(left)\n"
    + "            None => None\n"
    + "            Some((leftValue, leftRest)) =>\n"
    + "                match next(right)\n"
    + "                    None => None\n"
    + "                    Some((rightValue, rightRest)) =>\n"
    + "                        Some((combine(leftValue, rightValue), zipWith(leftRest, rightRest, combine)))\n"
    + "    })\n"
    + "\n"
    + "export let zip(left: Seq(a), right: Seq(b)): Seq((a, b)) =\n"
    + "    zipWith(left, right, (leftValue, rightValue) => (leftValue, rightValue))\n"
    + "\n"
    + "export fun concat(first: Seq(a), second: Seq(a)): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        match next(first)\n"
    + "            None => next(second)\n"
    + "            Some((value, rest)) => Some((value, concat(rest, second)))\n"
    + "    })\n"
    + "\n"
    + "// Combinators whose step may consume many source elements to yield one.\n"
    + "\n"
    + "export fun filter(source: Seq(a), keep: a -> Bool): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        var current = source\n"
    + "        var result = None\n"
    + "        var searching = True\n"
    + "        while searching\n"
    + "            match next(current)\n"
    + "                None => searching := False\n"
    + "                Some((value, rest)) =>\n"
    + "                    if keep(value) then\n"
    + "                        result := Some((value, filter(rest, keep)))\n"
    + "                        searching := False\n"
    + "                    else\n"
    + "                        current := rest\n"
    + "        result\n"
    + "    })\n"
    + "\n"
    + "export let drop(source: Seq(a), count: Int): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        var current = source\n"
    + "        var remaining = count\n"
    + "        var result = None\n"
    + "        var running = True\n"
    + "        while running\n"
    + "            if remaining <= 0 then\n"
    + "                result := next(current)\n"
    + "                running := False\n"
    + "            else\n"
    + "                match next(current)\n"
    + "                    None => running := False\n"
    + "                    Some((_, rest)) =>\n"
    + "                        current := rest\n"
    + "                        remaining := remaining - 1\n"
    + "        result\n"
    + "    })\n"
    + "\n"
    + "export let dropWhile(source: Seq(a), discard: a -> Bool): Seq(a) =\n"
    + "    Seq({ pull = () =>\n"
    + "        var current = source\n"
    + "        var result = None\n"
    + "        var searching = True\n"
    + "        while searching\n"
    + "            match next(current)\n"
    + "                None => searching := False\n"
    + "                Some((value, rest)) =>\n"
    + "                    if discard(value) then\n"
    + "                        current := rest\n"
    + "                    else\n"
    + "                        result := Some((value, rest))\n"
    + "                        searching := False\n"
    + "        result\n"
    + "    })\n"
    + "\n"
    + "// `flatMap` with the partially consumed inner sequence carried between pulls.\n"
    + "fun flatMapWith(source: Seq(a), transform: a -> Seq(b), pending: Seq(b)): Seq(b) =\n"
    + "    Seq({ pull = () =>\n"
    + "        var outer = source\n"
    + "        var inner = pending\n"
    + "        var result = None\n"
    + "        var searching = True\n"
    + "        while searching\n"
    + "            match next(inner)\n"
    + "                Some((value, rest)) =>\n"
    + "                    result := Some((value, flatMapWith(outer, transform, rest)))\n"
    + "                    searching := False\n"
    + "                None =>\n"
    + "                    match next(outer)\n"
    + "                        None => searching := False\n"
    + "                        Some((outerValue, outerRest)) =>\n"
    + "                            outer := outerRest\n"
    + "                            inner := transform(outerValue)\n"
    + "        result\n"
    + "    })\n"
    + "\n"
    + "export let flatMap(source: Seq(a), transform: a -> Seq(b)): Seq(b) =\n"
    + "    flatMapWith(source, transform, empty)\n"
    + "\n"
    + "// Consumers: drive a `Seq` to a value.\n"
    + "\n"
    + "export let fold(source: Seq(a), initial: b, combine: (b, a) -> b): b =\n"
    + "    var accumulator = initial\n"
    + "    var current = source\n"
    + "    var running = True\n"
    + "    while running\n"
    + "        match next(current)\n"
    + "            None => running := False\n"
    + "            Some((value, rest)) =>\n"
    + "                accumulator := combine(accumulator, value)\n"
    + "                current := rest\n"
    + "    accumulator\n"
    + "\n"
    + "export let length(source: Seq(a)): Int =\n"
    + "    var total = 0\n"
    + "    var current = source\n"
    + "    var running = True\n"
    + "    while running\n"
    + "        match next(current)\n"
    + "            None => running := False\n"
    + "            Some((_, rest)) =>\n"
    + "                total := total + 1\n"
    + "                current := rest\n"
    + "    total\n"
    + "\n"
    + "export let forEach(source: Seq(a), action: a -> Unit): Unit =\n"
    + "    var current = source\n"
    + "    var running = True\n"
    + "    while running\n"
    + "        match next(current)\n"
    + "            None => running := False\n"
    + "            Some((value, rest)) =>\n"
    + "                action(value)\n"
    + "                current := rest\n"
    + "\n"
    + "export let find(source: Seq(a), matches: a -> Bool): Option(a) =\n"
    + "    var current = source\n"
    + "    var result = None\n"
    + "    var searching = True\n"
    + "    while searching\n"
    + "        match next(current)\n"
    + "            None => searching := False\n"
    + "            Some((value, rest)) =>\n"
    + "                if matches(value) then\n"
    + "                    result := Some(value)\n"
    + "                    searching := False\n"
    + "                else\n"
    + "                    current := rest\n"
    + "    result\n"
    + "\n"
    + "export let any(source: Seq(a), matches: a -> Bool): Bool =\n"
    + "    match find(source, matches)\n"
    + "        None => False\n"
    + "        Some(_) => True\n"
    + "\n"
    + "export let all(source: Seq(a), matches: a -> Bool): Bool =\n"
    + "    not any(source, value => not matches(value))\n",
  "Result.hex":
    "// The canonical success-or-error union used across the standard library.\n"
    + "export union Result(a, e) =\n"
    + "    | Ok(value: a)\n"
    + "    | Err(error: e)\n",
};
